package com.ftk.tpip.catalog.domain.model;
import com.ftk.tpip.shared.AssetCode;import java.time.Instant;import java.util.Objects;
public record CanonicalCapability(Long id,long domainId,AssetCode capabilityCode,String capabilityName,String description,String ownerCode,CatalogAssetStatus status,long rowVersion,Instant createdAt,Instant updatedAt){
public CanonicalCapability{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(domainId<=0)throw new IllegalArgumentException("domainId must be positive");capabilityCode=Objects.requireNonNull(capabilityCode);capabilityName=req(capabilityName,"capabilityName",200);description=opt(description,1000);ownerCode=req(ownerCode,"ownerCode",100);status=Objects.requireNonNull(status);if(rowVersion<0)throw new IllegalArgumentException("rowVersion must not be negative");}
public static CanonicalCapability create(long domainId,AssetCode code,String name,String description,String owner){return new CanonicalCapability(null,domainId,code,name,description,owner,CatalogAssetStatus.ACTIVE,0,null,null);}public CanonicalCapability revise(String name,String description,String owner,CatalogAssetStatus status,long version){if(id==null)throw new IllegalStateException("unsaved capability cannot be revised");return new CanonicalCapability(id,domainId,capabilityCode,name,description,owner,status,version,createdAt,updatedAt);}private static String req(String v,String f,int m){String n=Objects.requireNonNull(v,f+" must not be null").trim();if(n.isEmpty()||n.length()>m)throw new IllegalArgumentException(f+" is blank or too long");return n;}private static String opt(String v,int m){if(v==null||v.isBlank())return null;String n=v.trim();if(n.length()>m)throw new IllegalArgumentException("description is too long");return n;}}
